import{_ as e,o,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Kế hoạch kỹ thuật","description":"","frontmatter":{},"headers":[],"relativePath":"feature/mobile-native-enhancements/plan.md","filePath":"feature/mobile-native-enhancements/plan.md"}'),c={name:"feature/mobile-native-enhancements/plan.md"};function d(h,t,i,r,s,l){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="ke-hoach-ky-thuat" tabindex="-1">Kế hoạch kỹ thuật <a class="header-anchor" href="#ke-hoach-ky-thuat" aria-label="Permalink to &quot;Kế hoạch kỹ thuật&quot;">​</a></h1><h2 id="thu-vien-them" tabindex="-1">Thư viện thêm <a class="header-anchor" href="#thu-vien-them" aria-label="Permalink to &quot;Thư viện thêm&quot;">​</a></h2><p><code>expo-linear-gradient</code>, <code>expo-haptics</code>, <code>expo-local-authentication</code>. <code>expo-notifications</code> đã có sẵn trong dependency nhưng trước đây chưa dùng. Cần build lại app native.</p><p><code>app.json</code> thêm plugin và quyền <code>POST_NOTIFICATIONS</code>, <code>USE_BIOMETRIC</code>, thêm câu giải thích Face ID. <code>android/</code> là thư mục sinh ra và bị ignore, nên khi prebuild lại quyền sẽ lấy từ <code>app.json</code>.</p><h2 id="thanh-phan" tabindex="-1">Thành phần <a class="header-anchor" href="#thanh-phan" aria-label="Permalink to &quot;Thành phần&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc</th><th>File</th></tr></thead><tbody><tr><td>Lưu cài đặt theo máy</td><td><code>src/store/deviceFeaturesStore.ts</code></td></tr><tr><td>Khoá ứng dụng</td><td><code>src/utils/appLock.ts</code>, <code>src/components/common/AppLockGate.tsx</code></td></tr><tr><td>Nhắc hạn</td><td><code>src/services/taskReminders.ts</code>, <code>src/hooks/useTaskReminders.ts</code>, <code>src/navigation/rootNavigation.ts</code></td></tr><tr><td>Báo mất mạng</td><td><code>src/components/common/OfflineBanner.tsx</code></td></tr><tr><td>Công tắc trong Cài đặt</td><td><code>src/components/settings/DeviceFeaturesSettings.tsx</code></td></tr><tr><td>Xúc giác</td><td><code>src/utils/haptics.ts</code>, <code>src/components/ui/Button.tsx</code></td></tr><tr><td>Dashboard</td><td><code>src/utils/dashboardStats.ts</code>, <code>src/components/dashboard/DashboardCharts.tsx</code> (thay <code>MockDashboardCharts</code>)</td></tr><tr><td>Hiệu ứng</td><td><code>src/components/ui/FadeIn.tsx</code>, <code>brandGradient</code> trong <code>src/theme/tokens.ts</code></td></tr><tr><td>Đa ngôn ngữ</td><td><code>src/i18n/locales/en.json</code></td></tr></tbody></table><h2 id="quyet-đinh" tabindex="-1">Quyết định <a class="header-anchor" href="#quyet-đinh" aria-label="Permalink to &quot;Quyết định&quot;">​</a></h2><ul><li><code>AppLockGate</code> phủ lên trên thay vì gỡ màn phía dưới, để upload và bản nháp không mất.</li><li>Chỉ tính giờ khi app vào <code>background</code>. Hộp xác minh của iOS đưa app qua <code>inactive</code>, nếu tính cả trạng thái này sẽ khoá lại ngay sau khi mở khoá.</li><li>Cài đặt lưu theo máy, không theo tài khoản, và vẫn còn sau khi đăng xuất.</li><li><code>FadeIn</code> dùng <code>Animated</code> của React Native theo <code>utils/motion</code>, vì <code>reanimated</code> không chạy được trong jest của dự án.</li></ul><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><ul><li>Lịch nhắc chỉ cập nhật khi mở app. Task đổi hạn lúc app đang đóng thì vẫn nhắc theo hạn cũ cho tới lần mở sau.</li><li>Máy không có khoá màn hình mà tắt khoá sau khi đã bật: màn khoá báo không xác minh được và chỉ còn nút Đăng xuất. Đây là chủ ý.</li></ul>',10)])])}const m=e(c,[["render",d]]);export{p as __pageData,m as default};
